<?php $layout='layouts.app'; use App\Components\Breadcrumb; use App\Components\Button; ?>
<?= Breadcrumb::render([['label'=>'Teachers','href'=>'/teachers'],['label'=>'Who Teaches What']]) ?>
<h1>Who Teaches What</h1><p class="subtitle">Mark the subjects each active teacher can teach. These general capabilities are separate from class-specific assignments.</p>
<?php if($teachers===[]||$subjects===[]): ?><p class="text-muted">Add at least one active teacher and one subject first.</p><?php else: ?><form method="POST" action="/teachers/subject-assignments/matrix"><?= csrf() ?><div class="table-wrap"><table class="table"><thead><tr><th>Teacher</th><?php foreach($subjects as $s): ?><th><?= e($s['name']) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($teachers as $t): ?><tr><td><?= e($t['first_name'].' '.$t['last_name']) ?></td><?php foreach($subjects as $s): ?><td><input type="checkbox" name="capabilities[<?= (int)$t['id'] ?>][<?= (int)$s['id'] ?>]" value="1" <?= isset($capabilities[$t['id']][$s['id']])?'checked':'' ?>></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><div style="margin-top:var(--space-4)"><?= Button::primary('Save capabilities',type:'submit') ?> <?= Button::outline('Back',href:'/teachers') ?></div></form><?php endif; ?>
